def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
    opp_d = n - opp_c
    my_d = n - my_c

    w10 = min(10, n)
    recent10_d = 0
    for a, b in history[-w10:]:
        if b == 'D':
            recent10_d += 1

    w5 = min(5, n)
    recent5_d = 0
    for a, b in history[-w5:]:
        if b == 'D':
            recent5_d += 1
    recent5_c = w5 - recent5_d

    w3 = min(3, n)
    recent3_d = 0
    for a, b in history[-w3:]:
        if b == 'D':
            recent3_d += 1
    recent3_c = w3 - recent3_d

    opp_d_streak = 0
    for a, b in reversed(history):
        if b == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for a, b in reversed(history):
        if a == 'D':
            my_d_streak += 1
        else:
            break

    forgive = 0
    punish = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D' and history[i - 1][1] == 'C':
            if history[i][1] == 'C':
                forgive += 1
            else:
                punish += 1

    if opp_d_streak >= 15 or opp_d == n:
        return 'D'

    if n >= 20 and opp_d > (4 * n) // 5 and recent10_d >= 8:
        return 'D'

    forgiving = forgive >= 1 and (punish == 0 or forgive >= 2 + 2 * punish)
    exploitable = forgiving and recent10_d <= 3 and opp_d <= max(3, n // 4)

    if last_opp == 'D':
        if last_me == 'C':
            if n >= 2 and history[-2][0] == 'D' and opp_d_streak <= 1:
                return 'C'
            if opp_d_streak >= 2 or recent3_c == 0:
                return 'D'
            return 'D'
        else:
            if opp_d_streak >= 3:
                return 'D'
            if opp_d_streak == 2:
                if my_d_streak >= 5 and recent5_c > 0:
                    return 'C'
                if recent5_c > 0 and n < 90:
                    return 'C'
                return 'D'
            if recent5_c > 0 or opp_c > 0:
                return 'C'
            return 'D'

    else:
        if last_me == 'D':
            if exploitable:
                return 'D'
            if n >= 96 and opp_d == 0 and forgive > 0:
                return 'D'
            return 'C'

        else:
            if exploitable:
                if recent10_d == 0 or (n >= 90 and recent10_d <= 1 and opp_d <= max(4, n // 6)):
                    return 'D'

            if n == 10 and opp_d == 0 and my_d == 0 and forgive == 0 and punish == 0:
                return 'D'

            return 'C'
